"""Canonical Unit 2 teaching explanations and exact catalog-voice models."""
from html import escape

AUDIO='/ingles/preintermedio-1/audio/unit2/lesson/'
audios={}
topics=[]
def say(key,text,voice='Narrator'):
    key='u2-'+key
    item={'text':text,'voice':voice,'path':AUDIO+key+'.mp3'}
    assert key not in audios or audios[key]==item
    audios[key]=item
    return f'<button type="button" class="pi-say" data-audio="{key}" aria-label="Listen: {escape(text,quote=True)}">{escape(text)}<span aria-hidden="true"> ♪</span></button>'
def card(title,body):return f'<article class="basic2-info-card pi-card"><h4>{title}</h4>{body}</article>'
def grid(*parts):return '<div class="pi-grid">'+''.join(parts)+'</div>'
def note(text):return '<p class="pi-note">'+text+'</p>'
def ex(key,text,why='',voice='Narrator'):return '<p class="pi-example">'+say(key,text,voice)+('</p><p class="pi-small">'+why if why else '')+'</p>'
def topic(group,id,title,goal,body):topics.append(dict(group=group,id=id,title=title,goal=goal,body=body))
def vocab(items):return grid(*(card(say(key,word),'<p>'+meaning+'</p>') for key,word,meaning in items))

topic(1,'free-time','Free-time activities','Distinguish interests, hobbies and free time, and describe the activities you choose.',
 grid(card('An interest','<p>A subject or activity you like learning about. You can be interested in music without playing an instrument.</p>'),card('A hobby','<p>An activity you do regularly for enjoyment: drawing, gardening or taking photos.</p>'),card('Free time','<p>Time outside work, study and other responsibilities. You can rest, spend time with others or practise a hobby.</p>'))+
 vocab([('drawing','drawing','Making pictures with pencils or similar materials.'),('photography','photography','Taking and creating photographs.'),('gardening','gardening','Growing or caring for plants.'),('reading','reading','Enjoying books, stories or articles.'),('making-jewellery','making jewellery','Creating bracelets, necklaces or other decorative items.'),('playing-guitar','playing the guitar','Making music with a guitar.')])+
 grid(card('Inside and outside','<p><b>Indoor:</b> reading, making jewellery, playing board games.</p><p><b>Outdoor:</b> gardening, cycling, going for a walk.</p><p>Some hobbies can happen in either place. Photography is one example.</p>'),card('Alone or with others',ex('free-time-example','I enjoy taking photos, but I also like playing board games with friends.')+'<p>These are different ways to spend free time. Explain your own choice with <b>because</b>.</p>'))+
 note('Recover the Unit 1 patterns: <b>What do you do in your free time?</b> and <b>I enjoy + verb-ing</b>. Add a useful detail rather than memorising a long list.'))

topic(1,'music','Music and preferences','Talk about music genres and explain a preference clearly.',
 vocab([('pop','pop','Popular music with memorable melodies.'),('rock','rock','A broad genre often featuring electric guitars and drums.'),('jazz','jazz','A broad musical tradition often including improvisation.'),('classical','classical music','A broad tradition including orchestral and chamber music.'),('salsa','salsa','A dance music genre with Afro-Caribbean roots.'),('reggaeton','reggaeton','A popular genre associated with a recognisable rhythmic pattern.')])+
 grid(card('Ask about a genre',ex('music-question','What kind of music do you like?')+'<p>I like salsa because I enjoy the rhythm.</p>'),card('Artist, singer, band or song?','<p>An <b>artist</b> creates or performs music. A <b>singer</b> sings. A <b>band</b> is a group of musicians. A <b>song</b> is one piece of music, usually with words.</p><p><b>What is your favourite song?</b><br><b>Who is your favourite singer?</b></p>'),card('Describe a preference',ex('music-preference','I prefer jazz when I read, but I listen to salsa with my friends.')))+
 note('Musicians can work in more than one genre. A class popularity chart shows the preferences of that group, not a universal ranking.'))

pronouns=[('I','me','Can you help me?'),('you','you','We can invite you.'),('he','him','I play tennis with him.'),('she','her','We listen to her.'),('it','it','I like this activity. I enjoy it.'),('we','us','You can join us.'),('they','them','I like these songs. I listen to them often.')]
topic(1,'object-pronouns','Object pronouns','Choose the pronoun for the person or thing receiving an action or following a preposition.',
 '<div class="pi-compare"><div><p class="pi-label">Subject</p><p><b>She</b> plays the guitar.</p><p>She tells us who does the action.</p></div><div><p class="pi-label">Object</p><p>I listen to <b>her</b>.</p><p>Her refers to the person I listen to. It follows the preposition <b>to</b>.</p></div></div>'+
 grid(*(card(subject+' → '+obj,ex('pronoun-'+obj,text)) for subject,obj,text in pronouns))+
 grid(card('After a verb','<p><b>verb + object pronoun</b></p><p>Help <b>me</b>. Invite <b>them</b>. Join <b>us</b>.</p><p>Keep the pronoun in the object position: “My friends invite <b>me</b>,” not “invite I”.</p>'),card('After a preposition','<p><b>with + him/her/us/them</b><br><b>to + him/her/it/them</b><br><b>for + me/you/us</b></p><p>I play with <b>him</b>. I listen to <b>them</b>. This invitation is for <b>you</b>.</p>'),card('Make the reference clear',ex('reference','This band is great. I listen to them every day.')+'<p><b>Them</b> refers to the musicians in the band. For one song, use <b>it</b>: “This song is great. I like it.”</p>'))+
 note('<b>She</b> and <b>her</b> refer to the same person, but do different jobs. Correct: “I listen to <b>her</b>.” Incorrect: “I listen to she.” An object pronoun replaces a clear noun or noun phrase.'))

topic(1,'abilities','Abilities with can','Say what someone can do and ask about an ability without adding to or a third-person s.',
 grid(card('Affirmative','<p><b>subject + can + base verb</b></p>'+ex('can-affirmative','She can play the guitar.')+'<p>I can swim. They can draw. The form of <b>can</b> stays the same with every subject.</p>'),card('Negative','<p><b>subject + cannot / can’t + base verb</b></p>'+ex('can-negative','I can draw, but I can’t play tennis.')+'<p><b>Cannot</b> is normally written as one word. <b>Can’t</b> is the contraction.</p>'),card('Questions and short answers','<p><b>Can + subject + base verb?</b></p>'+ex('can-question','Can you play the guitar?')+ex('can-answer','Yes, I can. No, I can’t.')+'<p><b>What can you make?</b><br>I can make bracelets.</p>'))+
 '<div class="pi-compare"><div><b>Present simple</b><p>She <b>plays</b> tennis.<br><b>Does</b> she play tennis?</p></div><div><b>With can</b><p>She <b>can play</b> tennis.<br><b>Can</b> she play tennis?</p></div></div>'+
 note('Correct: <b>She can play.</b> Avoid “She can plays”, “She can to play” and “Does she can play?” For this section, can expresses ability.'))

topic(2,'making-things','Making things','Name materials, actions and handmade activities before explaining a small project.',
 vocab([('beads','beads','Small decorative objects with holes for thread.'),('thread','thread','A thin strand used in sewing or craft work.'),('wood','wood','Material from trees used to build or make things.'),('paper','paper','Material used for drawing, folding or writing.'),('paint','paint','A coloured substance used to decorate a surface.'),('brush','brush','A tool used to apply paint.')])+
 grid(card('Activities','<p><b>Jewellery making:</b> making bracelets or necklaces.</p><p><b>Woodworking:</b> making things from wood. <b>Carpentry</b> is related work that often involves building or fitting wooden structures.</p><p><b>Painting:</b> creating pictures or decorating a surface with paint.</p>'),card('Actions','<p><b>make</b> a bracelet · <b>build</b> a small boat · <b>paint</b> a picture · <b>cut</b> thread · <b>choose</b> colours · <b>add</b> beads</p>'+ex('craft-example','I use small beads and thread to make necklaces.')))+
 note('<b>Handy work</b> is the label in the course guide. In this explanation, <b>crafts</b> and <b>making things</b> describe the hobby context more directly. Learn the action together with its object.'))

topic(2,'purpose','Purpose and simple instructions','Explain what a material is for and follow a short sequence using action verbs.',
 grid(card('Ask about purpose',ex('purpose-question','What do you use the thread for?')+'<p><b>What for?</b> is a shorter question when the object is already clear.</p>'),card('Explain the purpose',ex('purpose-answer','I use it to make bracelets.')+'<p><b>use + material / it + to + base verb</b><br>We use wood <b>to build</b> a small boat.</p><p>To make tells us the purpose. It does not mean the action is happening now.</p>'))+
 '<div class="pi-process"><div><b>First</b><p>Choose two colours.</p></div><span aria-hidden="true">→</span><div><b>Then</b><p>Cut a piece of thread.</p></div><span aria-hidden="true">→</span><div><b>After that</b><p>Add the beads.</p></div><span aria-hidden="true">→</span><div><b>Finally</b><p>Tie the ends.</p></div></div>'+
 note('An instruction often begins with the <b>base verb</b>: choose, cut, add, tie. The subject you is understood. These examples illustrate the language of a sequence. The subject you is understood in each instruction.'))

topic(2,'sports','Sports and activity patterns','Use familiar sports expressions and ask how two activities are different.',
 grid(card('play + sport or game',ex('play','play soccer, play tennis, play basketball')+'<p>Use these complete expressions. Play is common with ball sports and games.</p>'),card('go + activity in -ing',ex('go','go swimming, go cycling, go hiking')+'<p>Do not insert to: <b>I go swimming</b>, not “I go to swimming”.</p>'),card('do + activity',ex('do','do yoga, do karate, do exercise')+'<p>These are common combinations. The patterns are useful guides; learn each activity with its usual verb.</p>'))+
 grid(card('Ask about a sport','<p><b>How do you play this sport?</b><br>Explain the players, main action and a simple rule.</p><p><b>Where is it popular?</b><br>Use information provided in the lesson or an appropriate source.</p>'),card('Ask about a difference',ex('difference-question','What is the difference between soccer and basketball?')+'<p>Use <b>between A and B</b>. A simple answer can name an important feature: “In soccer, players usually use their feet. In basketball, they use their hands.”</p>'))+
 note('For an earnings question, use <b>How much does a soccer player earn?</b> After does, use the base form earn, not earns. Actual earnings vary; the language example does not require memorising a salary.'))

topic(2,'habits-now','Habits and actions in progress','Choose the tense according to time and distinguish an activity name from a continuous verb.',
 grid(card('A repeated activity',ex('habit','I make jewellery on weekends.')+'<p><b>Present simple:</b> a regular activity.<br>She makes jewellery on Saturdays.</p><p><b>Do you make bracelets?</b><br>Yes, I do. / No, I don’t.</p>'),card('An action in progress',ex('now','I’m making a necklace now.')+'<p><b>am/is/are + verb-ing:</b> an action in progress now or around now.</p><p><b>What are you making?</b><br>I’m making a necklace.</p>'),card('An activity after enjoy','<p><b>I enjoy making things.</b></p><p>Here, making names the activity I enjoy. It is not a continuous tense because there is no am/is/are before making.</p><p><b>I’m making something.</b><br>Here, am making is the continuous verb.</p>'))+
 note('Compare <b>every weekend</b> with <b>right now</b>. Changing the tense changes the time meaning. This section applies language from Basic 2 rather than presenting a new tense.'))

topic(3,'nature','Nature and outdoor hobbies','Describe a natural place and connect it to an outdoor activity.',
 vocab([('forest','forest','An area with many trees.'),('river','river','Water flowing along a natural channel.'),('lake','lake','A body of water surrounded by land.'),('trail','trail','A path used for walking or other outdoor activities.'),('hill','hill','An area of land higher than the ground around it.'),('waterfall','waterfall','Water falling from a height.')])+
 grid(card('Outdoor hobbies',ex('outdoors','I like hiking and being outdoors.')+'<p><b>Hiking:</b> walking on trails, often in natural areas.<br><b>Camping:</b> staying outdoors, usually in a tent.<br><b>Birdwatching:</b> observing birds.</p>'),card('Describe a place','<p>Choose a precise detail: <b>quiet, green, rocky, shady, steep</b>.</p><p>The trail is shady. There is a river near the forest. I like this place because it is quiet.</p>'))+
 note('Use the information in a map or description. A simple nature description can include one responsible habit: <b>We take our rubbish home.</b> This connects the outdoor topic with care for the environment.'))

questions=[('duration','How long does the activity last?','Duration','It lasts two hours.','Ask about time, not distance.'),('distance','How far is the lake from the meeting point?','Distance','It is two kilometres away.','Ask how distant one place is from another.'),('frequency','How often do you go hiking?','Frequency','Twice a month.','Ask how regularly an activity happens.'),('price','How much does the class cost?','Price','It costs twenty dollars.','Ask the price of an activity or service.')]
topic(3,'information-questions','Useful information questions','Distinguish duration, distance, frequency and price before answering.',
 grid(*(card(label,ex(key,question)+'<p><b>'+answer+'</b></p><p>'+why+'</p>') for key,question,label,answer,why in questions))+
 grid(card('How much can ask for an amount','<p><b>How much thread do we need?</b><br>We need one metre.</p><p><b>How much does the thread cost?</b><br>It costs two dollars.</p><p>The first question asks for an amount. The second asks for a price.</p>'),card('Use a base verb after does','<p>How long does it <b>last</b>?<br>How much does it <b>cost</b>?</p><p>Answer: It <b>lasts</b> two hours. It <b>costs</b> twenty dollars.</p>'))+
 note('The times, distances and prices here are fictional teaching examples. They show what kind of information each question requests.'))

topic(3,'location-sequence','Location and sequence','Locate a place, organise steps and recognise common contractions.',
 '<figure class="pi-teaching-map"><svg viewBox="0 0 700 260" role="img" aria-labelledby="hobby-map-title"><title id="hobby-map-title">Fictional hobby park map: forest on the left, lake in the centre, meeting point on the right, trail in front of the lake and campsite behind it</title><rect x="5" y="5" width="690" height="250" rx="20" fill="#eef4ff"/><path d="M55 205 Q220 155 360 210 T640 205" fill="none" stroke="#b97914" stroke-width="12"/><g fill="#17623c"><path d="M85 40l-35 75h70z"/><path d="M145 45l-35 75h70z"/></g><ellipse cx="350" cy="125" rx="85" ry="40" fill="#add6f5" stroke="#123b8f" stroke-width="3"/><path d="M530 115h100v55H530z" fill="white" stroke="#071f4f" stroke-width="3"/><path d="M520 115l60-40 60 40" fill="#d7193f"/><path d="M315 55l35-40 35 40z" fill="#d88a15"/><g fill="#071f4f" font-family="Arial, sans-serif" font-size="19" text-anchor="middle"><text x="110" y="145">Forest</text><text x="350" y="130">Lake</text><text x="350" y="78">Campsite</text><text x="580" y="195">Meeting point</text><text x="280" y="242">Trail</text></g></svg><figcaption>Fictional map. Use the labels and this viewing direction for the location examples.</figcaption></figure>'+
 grid(card('Where is it?',ex('location','The trail is in front of the lake. The campsite is behind it.')+'<p><b>behind</b>, not “behind of”.<br><b>in front of</b>, with of.</p><p>The forest is <b>near</b> the lake. The meeting point is <b>to the right of</b> the lake.</p>'),card('When does it happen?','<p><b>before / after</b> place events in time:<br>We meet <b>before</b> the walk.<br>We rest <b>after</b> the activity.</p><p><b>First, then, after that, finally</b> organise steps. Location words and sequence words answer different questions.</p>'),card('Short forms in context',ex('contractions',"Who’s in the hobby group? He’s my classmate.")+'<p><b>Who’s = who is</b> here.<br><b>He’s = he is</b> here.<br><b>She’s making a bracelet = she is making a bracelet.</b></p><p>The context tells you which words have been shortened.</p>')))

topic(4,'hobby-groups','Joining and describing a group','Combine interests, abilities and information questions to understand a hobby group.',
 grid(card('What a useful group description includes','<ol><li>What the group enjoys.</li><li>What members can do.</li><li>When and where they meet.</li><li>What they usually do and what they are doing now.</li><li>A purpose and an invitation.</li></ol>'),card('Ask before joining','<p>What do you do in the group?<br>Can beginners join?<br>How often do you meet?<br>How long does each meeting last?<br>How much does it cost?</p>'),card('Connect to the group',ex('join-us','We meet on Saturdays. You can join us.')+'<p><b>Us</b> refers to the members of the group. Use it to connect the invitation with the people already introduced.</p>'))+
 note('The group profile is an explained language model: it connects the activity, the members, the schedule and the invitation.'))

expressions=[('take-up','Phrasal verb','take up','empezar una afición','Begin an activity as a hobby.','Everyday, neutral. Put the activity after take up.','You can take up photography.'),('try-out','Phrasal verb','try out','probar para ver cómo funciona','Test an activity, method or piece of equipment.','Everyday, neutral. With a pronoun: try it out.','We can try out a new game.'),('join-in','Phrasal verb','join in','participar','Take part in an activity with other people.','Everyday, neutral. Use join us for the people, or join in for participation.','Can I join in?'),('hang-of','Idiom','get the hang of','empezar a dominar algo','Learn how to do something through practice.','Informal, common. Follow of with an activity or a noun.','I’m getting the hang of making bracelets.'),('cup-tea','Idiom','not my cup of tea','no ser lo mío','Say that something is not your preference.','Conversational. It expresses a personal preference.','Camping is not my cup of tea, but I enjoy hiking.')]
expressions_html=grid(*(card('<span class="pi-label">'+kind+'</span>'+say(key,phrase),'<p class="pi-spanish">'+spanish+'</p><p>'+meaning+'</p><p class="pi-small"><b>Use:</b> '+register+'</p>'+ex(key+'-example',sample)) for key,kind,phrase,spanish,meaning,register,sample in expressions))
topic(4,'hobby-expressions','Expressions for interests and hobbies','Understand natural multiword expressions and use one in a complete context.',expressions_html+note('The Spanish explanation gives an approximate meaning. Learn the English example and context rather than translating the expression word by word.'))

dialogue=[('Laura','Hi, Mateo. What do you do in your free time?'),('Mateo','I enjoy listening to music and making things. What about you?'),('Laura','I like salsa. I listen to it when I paint. Can you make bracelets?'),('Mateo','Yes, I can. I use beads and thread to make them.'),('Laura','What are you making today?'),('Mateo','I’m making a necklace. Our group usually meets on Saturdays.'),('Laura','How long does each meeting last?'),('Mateo','Two hours. You can join us and try out a new activity.')]
dialogue_html='<div class="pi-dialogue">'+''.join('<article class="pi-dialogue-line"><span class="pi-label">'+role+'</span>'+say('dialogue-'+str(i+1),text,role)+'</article>' for i,(role,text) in enumerate(dialogue))+'</div>'
project='Our project is a simple bracelet. We use beads and thread to make it. First, we choose two colours. Then, we cut a piece of thread. After that, we add the beads. Finally, we tie the ends. The bracelet is ready.'
group='We are a small craft group. We enjoy making jewellery. Some members can paint, and others can make bracelets. We meet on Saturdays. Today, we are making necklaces. We use beads and thread to make them. Each meeting lasts two hours. You can join us.'
blog='Our favourite outdoor place is a small lake near a forest. The trail is shady, and the meeting point is in front of a small building. The lake is two kilometres from the meeting point. We go hiking twice a month. Our walks usually last two hours. We enjoy being outdoors, and we take our rubbish home.'
topic(4,'complete-models','Complete language models','Notice how a conversation, a project description and a group profile combine the unit language.',
 '<p>These fictional conversations and descriptions are worked examples. They show how the unit language connects in a complete text.</p><button type="button" class="btn btn-primary pi-button" data-playlist="'+','.join('u2-dialogue-'+str(i+1) for i in range(len(dialogue)))+'">Listen to the conversation</button>'+dialogue_html+
 grid(card('A craft description: explained model',ex('project-model',project)),card('Our hobby group',ex('group-model',group)),card('A short nature blog',ex('nature-blog',blog)))+
 note('<b>Notice:</b> in the dialogue, <b>it</b> refers to salsa and <b>them</b> refers to bracelets. In the project model, <b>it</b> refers to the bracelet. In the group profile, <b>them</b> refers to necklaces and <b>us</b> refers to the members. Always look back at the noun to identify the reference.'))

topic(4,'unit-2-summary','Unit summary','Recognise the vocabulary, grammar and communication goals connected by the examples.',
 '<ul class="pi-checklist">'+''.join('<li>'+x+'</li>' for x in ['I can describe my interests and explain a preference.','I can use object pronouns with a clear reference.','I can say what I can and can’t do.','I can ask and answer questions with can.','I can describe a hobby and explain a simple purpose.','I can distinguish a habit from an action in progress.','I can ask about duration, distance, frequency and price.','I can describe a natural place and locate its features.','I can understand and introduce a hobby group.'])+'</ul>')

clusters=[(1,'leisure-music','Leisure Time and Music','Interests, music, object pronouns and abilities.'),(2,'crafts-sports','Handy Work and Sports','Materials, purpose, sports and actions in context.'),(3,'natural-world','The Natural World','Places, outdoor activities and useful information.'),(4,'groups-models','Hobby Groups','Group descriptions, expressions and complete models.')]
